<?php require_once __DIR__.'/includes/functions.php';require_role(['admin']);$rows=$conn->query("SELECT l.*,u.full_name FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.id DESC LIMIT 300");include 'includes/header.php';?><h3 class="mb-3">Activity Logs</h3><div class="panel table-responsive"><table class="table"><thead><tr><th>Date/time</th><th>User</th><th>Action</th><th>Details</th><th>IP</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['full_name']??'Deleted user')?></td><td><?=e($r['action'])?></td><td><?=e($r['details'])?></td><td><?=e($r['ip_address'])?></td></tr><?php endwhile;?></tbody></table></div><?php include 'includes/footer.php';?>
